export function classifyHand(p){const d=(a,b)=>Math.hypot(p[a].x-p[b].x,p[a].y-p[b].y);const extended=[[8,6],[12,10],[16,14],[20,18]].map(([tip,pip])=>d(tip,0)>d(pip,0)*1.15);if(extended[0]&&extended[1]&&!extended[2]&&!extended[3])return 'victory';if(extended.every(Boolean))return 'open';if(extended.every(v=>!v))return 'fist';return 'other'}
